  function emptyState(settings={}) { return { customers:[], products:[], invoices:[], payments:[], orders:[], purchases:[], expenses:[], movements:[], employees:[], settings:{ ...settings, businessName:settings.businessName||'My Wholesale Business', invoicePrefix:settings.invoicePrefix||'INV', invoiceNext:1, orderNext:1 }, sample:false }; }
  function load() { try { const saved=localStorage.getItem(KEY); return saved ? JSON.parse(saved) : seed(); } catch { return seed(); } }
  let db = load();
  let page = 'dashboard';
  let query = '';
  let toastTimer;
  const root = document.getElementById('app');
  const modal = document.getElementById('modal');
  const toastBox = document.getElementById('toast');
  const routes = [
    ['dashboard','Overview','grid'],['customers','Customers','people'],['products','Products','box'],['billing','New bill','bill'],['orders','Orders','cart'],['payments','Payments','wallet'],['inventory','Inventory','bars'],['purchases','Purchases','truck'],['expenses','Expenses','wallet'],['reports','Reports','bars'],['employees','Team','people'],['settings','Settings','gear']
  ];
  const routeInfo = Object.fromEntries(routes.map(([id,label,ic])=>[id,{label,ic}]));
  const save = () => {
    try { localStorage.setItem(KEY, JSON.stringify(db)); return true; }
    catch { setTimeout(()=>toast('This browser could not save the record. Check device storage and try again.',true),0); return false; }
  };
  const customer = id => db.customers.find(c=>c.id===id);
  const allVariants = () => db.products.flatMap(p=>p.variants.map(v=>({...v,productId:p.id,productName:p.name,category:p.category,hsn:p.hsn})));
  const findVariant = id => allVariants().find(v=>v.id===id);
  const invOutstanding = i => Math.max(0, round(i.grandTotal-num(i.paid)));
  const dueFor = id => round(num(customer(id)?.opening) + db.invoices.filter(i=>i.customerId===id).reduce((s,i)=>s+num(i.grandTotal),0) - db.payments.filter(p=>p.customerId===id).reduce((s,p)=>s+num(p.amount),0));
  const totalSales = (list=db.invoices) => round(list.reduce((s,i)=>s+num(i.grandTotal),0));
  const fmtDateTime = s => dateText(s);
  const badge = (text, kind='neutral') => `<span class="badge ${kind}">${esc(text)}</span>`;
  const initials = name => String(name||'M').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const sumBags = items => items.reduce((n,x)=>n+num(x.qty),0);
  const sumWeight = items => items.reduce((n,x)=>n+num(x.weight)*num(x.qty),0);
  const weightLabel = n => n >= 1 ? `${Number(n.toFixed(2))} kg` : `${Math.round(n*1000)} g`;
  const btn = (label,action,kind='secondary',ic='') => `<button class="btn ${kind}" data-action="${action}">${ic?icon(ic,16):''}<span>${label}</span></button>`;
  const blank = (title,desc,action,label,ic='plus') => `<div class="empty"><div class="empty-mark">${icon(ic,21)}</div><h3>${title}</h3><p>${desc}</p>${action?btn(label,action,'primary','plus'):''}</div>`;
