    if(type==='expense') { openModal('Add expense',`<form id="expense-form"><div class="form-grid"><label class="field"><span>Category *</span><select name="category">${['Transportation','Rent','Salaries','Electricity','Packaging','Maintenance','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Amount (₹) *</span><input name="amount" type="number" min="0.01" step="0.01" required></label><label class="field"><span>Date *</span><input name="date" type="date" value="${today()}" required></label><label class="field"><span>Payment method</span><select name="method"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option><option>Other</option></select></label><label class="field span-2"><span>Description</span><input name="description" placeholder="What was this expense for?"></label><label class="field span-2"><span>Notes</span><textarea name="notes" rows="2"></textarea></label></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Save expense</button></div></form>`,'wide'); return; }
    if(type==='employee') { openModal('Add team member',`<form id="employee-form"><div class="form-grid"><label class="field"><span>Name *</span><input name="name" required></label><label class="field"><span>Mobile number</span><input name="phone" inputmode="tel"></label><label class="field"><span>Role *</span><select name="role"><option>Sales Executive</option><option>Manager</option><option>Billing Staff</option><option>Inventory Staff</option></select></label><label class="field"><span>Status</span><select name="status"><option>Active</option><option>Inactive</option></select></label></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Save team member</button></div></form>`); }
